SourceCode.Declaration:
/// <summary>
/// Chain of Command extension on <c>DirPersonName</c> to detect when <c>FirstName</c>, <c>MiddleName</c>,
/// or <c>LastName</c> is inserted or updated on a <c>DirPerson</c> party and enqueue the linked <c>CustTable</c>.
/// </summary>
[ExtensionOf(tableStr(DirPersonName))]
public final class UTCSFDirPersonName_Extension
{
}

Method.Source:
public void insert()
{
    boolean hasName = (strLRTrim(this.FirstName)  != ''
                    || strLRTrim(this.MiddleName) != ''
                    || strLRTrim(this.LastName)   != '');

    next insert();

    if (hasName && this.Person)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByPartyRecId(this.Person);
    }
}

public void update()
{
    DirPersonName origName      = this.orig();
    boolean       hasNameChange = (this.FirstName  != origName.FirstName
                                || this.MiddleName != origName.MiddleName
                                || this.LastName   != origName.LastName);

    next update();

    if (hasNameChange && this.Person)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByPartyRecId(this.Person);
    }
}
